/// Every bind group layout, built once and indexed by [`LayoutId`].
struct Layouts([wgpu::BindGroupLayout; LAYOUT_COUNT]);

impl Layouts {
    fn new(device: &wgpu::Device) -> Layouts {
        Layouts(std::array::from_fn(|slot| {
            let desc = &LAYOUTS[slot];
            assert_eq!(
                desc.id as usize, slot,
                "the layout registry must be ordered by LayoutId — `get` indexes by discriminant",
            );
            (desc.create)(device)
        }))
    }

    fn get(&self, id: LayoutId) -> &wgpu::BindGroupLayout {
        &self.0[id as usize]
    }
}

/// One shader's pipelines; the mesh-geometry shaders also carry a winding-reversed twin.
struct ShaderPipelines {
    main: wgpu::RenderPipeline,
    mirrored: Option<wgpu::RenderPipeline>,
}

/// Builds the pipelines shader `id` feeds, from `src` and the layouts its registry row names. The
/// single construction point both `Renderer::new` (compiled-in source) and [`Renderer::reload_shader`]
/// (reloaded source) route through, so a reload rebuilds exactly what the initial build built.
///
/// The match is the genuinely per-shader half — vertex buffers, blend state, depth policy, color
/// target. Everything uniform across shaders (which layouts, in which group order) is the registry
/// row.
fn build_pipeline(
    device: &wgpu::Device,
    id: ShaderId,
    src: &str,
    layouts: &Layouts,
) -> ShaderPipelines {
    let label = id.label();
    let bind_group_layouts: Vec<Option<&wgpu::BindGroupLayout>> = id
        .desc()
        .layouts
        .iter()
        .map(|&layout| Some(layouts.get(layout)))
        .collect();
    let layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some(label),
        bind_group_layouts: &bind_group_layouts,
        immediate_size: 0,
    });
    let twinned = |build: fn(
        &wgpu::Device,
        &str,
        &str,
        &wgpu::PipelineLayout,
        wgpu::FrontFace,
    ) -> wgpu::RenderPipeline| ShaderPipelines {
        main: build(device, label, src, &layout, wgpu::FrontFace::Ccw),
        mirrored: Some(build(device, label, src, &layout, wgpu::FrontFace::Cw)),
    };
    let main = match id {
        ShaderId::Mesh => return twinned(build_mesh_pipeline),
        ShaderId::Shadow => return twinned(build_shadow_pipeline),
        ShaderId::Prepass => return twinned(build_prepass_pipeline),
        ShaderId::Sky => build_sky_pipeline(device, label, src, &layout),
        ShaderId::GroundMarker => build_ground_marker_pipeline(device, label, src, &layout),
        ShaderId::Sprite => build_sprite_pipeline(device, label, src, &layout),
        ShaderId::Particle => build_particle_pipeline(device, label, src, &layout),
        ShaderId::Text => build_text_pipeline(device, label, src, &layout),
        // The AO, shaft and depth-of-field chains work in `Rgba16Float` like the bloom chain: a
        // half-float target keeps their intermediates linear and filterable with no new graph texture
        // format, where the only 8-bit format the graph offers is sRGB-encoded and would be outright
        // wrong for the normals the prepass writes, the HDR colour the DoF chain carries, or the
        // *signed* circle of confusion it packs beside it.
        ShaderId::Ssao
        | ShaderId::Shafts
        | ShaderId::DofCoc
        | ShaderId::Dof
        | ShaderId::BoxBlur
        | ShaderId::Threshold
        | ShaderId::BloomDown
        | ShaderId::BloomUp => build_fullscreen_pipeline(device, label, src, &layout, HDR_FORMAT),
        // `blit` is the overlay pass's passthrough copy of the composited LDR image, and `resolve`
        // and `upscale` are the two directions of the render scale's resampling; all four write the
        // LDR sRGB output.
        ShaderId::Composite | ShaderId::Resolve | ShaderId::Upscale | ShaderId::Blit => {
            build_fullscreen_pipeline(device, label, src, &layout, OUTPUT_FORMAT)
        }
        ShaderId::UiRect => build_ui_rect_pipeline(device, label, src, &layout),
        ShaderId::UiText => build_ui_text_pipeline(device, label, src, &layout),
        ShaderId::DebugLine => build_debug_line_pipeline(device, label, src, &layout),
    };
    ShaderPipelines {
        main,
        mirrored: None,
    }
}

/// Validates reloaded WGSL with naga — the exact front-end and validator wgpu runs at
/// `create_shader_module` — so a parse/type error becomes a readable `L2009` and never reaches the
/// GPU (keep-last-good: the caller returns before touching the live pipeline).
fn validate_wgsl(id: ShaderId, source: &str) -> Result<(), Diagnostic> {
    let module = naga::front::wgsl::parse_str(source).map_err(|e| {
        Diagnostic::new(
            code::SHADER_RELOAD_INVALID,
            format!(
                "{}: reloaded WGSL failed to parse — the previous shader stays live\n{}",
                id.file_name(),
                e.emit_to_string(source),
            ),
        )
    })?;
    naga::valid::Validator::new(
        naga::valid::ValidationFlags::default(),
        naga::valid::Capabilities::default(),
    )
    .validate(&module)
    .map_err(|e| {
        Diagnostic::new(
            code::SHADER_RELOAD_INVALID,
            format!(
                "{}: reloaded WGSL failed validation — the previous shader stays live\n{}",
                id.file_name(),
                e.emit_to_string(source),
            ),
        )
    })?;
    Ok(())
}

/// The `L2009` for a reloaded shader that parsed and validated but whose recreated pipeline is
/// incompatible with the fixed, size-pinned bind group layouts (a binding-shape change). The wgpu
/// error scope caught it, so the previous pipeline is untouched.
fn pipeline_incompatible(id: ShaderId, error: wgpu::Error) -> Diagnostic {
    Diagnostic::new(
        code::SHADER_RELOAD_INVALID,
        format!(
            "{}: the reloaded shader's pipeline is incompatible with the existing bind group \
             layouts (a binding-shape change) — the previous shader stays live\n{error}",
            id.file_name(),
        ),
    )
    .with_help(
        "a hot-reloaded shader may change only its body, not its interface: keep uniform/struct \
         sizes and @group/@binding slots as they were, or rebuild the engine to change them",
    )
}

fn alpha_blend() -> wgpu::BlendState {
    wgpu::BlendState {
        color: wgpu::BlendComponent {
            src_factor: wgpu::BlendFactor::SrcAlpha,
            dst_factor: wgpu::BlendFactor::OneMinusSrcAlpha,
            operation: wgpu::BlendOperation::Add,
        },
        alpha: wgpu::BlendComponent {
            src_factor: wgpu::BlendFactor::One,
            dst_factor: wgpu::BlendFactor::OneMinusSrcAlpha,
            operation: wgpu::BlendOperation::Add,
        },
    }
}

/// The premultiplied-alpha blend: `src + dst * (1 - src.a)` on colour and alpha alike.
///
/// The counterpart of [`alpha_blend`] for a shader that has already weighted its colour by its
/// coverage. What it buys beyond symmetry is the additive path: a fragment that reports zero alpha
/// never attenuates the destination, so its weighted colour is simply added — which is why alpha and
/// additive particles need only one pipeline between them.
fn premultiplied_blend() -> wgpu::BlendState {
    let component = wgpu::BlendComponent {
        src_factor: wgpu::BlendFactor::One,
        dst_factor: wgpu::BlendFactor::OneMinusSrcAlpha,
        operation: wgpu::BlendOperation::Add,
    };
    wgpu::BlendState {
        color: component,
        alpha: component,
    }
}

fn depth_state(write: bool, compare: wgpu::CompareFunction) -> wgpu::DepthStencilState {
    wgpu::DepthStencilState {
        format: DEPTH_FORMAT,
        depth_write_enabled: Some(write),
        depth_compare: Some(compare),
        stencil: wgpu::StencilState::default(),
        bias: wgpu::DepthBiasState::default(),
    }
}

fn module(device: &wgpu::Device, label: &str, src: &str) -> wgpu::ShaderModule {
    device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some(label),
        source: wgpu::ShaderSource::Wgsl(std::borrow::Cow::Borrowed(src)),
    })
}

// The hand-written vertex-buffer attribute layouts. WGSL does not express the packing / two-buffer
// split / step modes (fact in Plan/shader-bindgen.md), so these stay hand-authored — but their
// `(shader_location, format)` lists ARE reflectable, and `vertex_inputs_match_generated_reflection`
// pins each one to the generated `*_VS_MAIN_INPUTS` (out of the WGSL). Edit here AND the WGSL together.

/// Mesh per-vertex attributes (`MeshVertex`: position/normal/color/material/uv/tangent/weights/bones),
/// locations 0-5 then 18-19 (the macro's sequential offsets are correct because the two skin fields
/// are declared last in `MeshVertex`, right after `tangent`).
const MESH_VERTEX_ATTRS: [wgpu::VertexAttribute; 8] = wgpu::vertex_attr_array![0 => Float32x3, 1 => Float32x3, 2 => Float32x4, 3 => Float32x3, 4 => Float32x2, 5 => Float32x4, 18 => Float32x4, 19 => Uint32x4];
/// Mesh per-instance attributes (`MeshInstanceRaw`): model rows 6-9, color 10, material 11,
/// normal-matrix rows 12-15, occlusion-fade lane 16, hit-flash lane 17.
const MESH_INSTANCE_ATTRS: [wgpu::VertexAttribute; 12] = wgpu::vertex_attr_array![6 => Float32x4, 7 => Float32x4, 8 => Float32x4, 9 => Float32x4, 10 => Float32x4, 11 => Float32x4, 12 => Float32x4, 13 => Float32x4, 14 => Float32x4, 15 => Float32x4, 16 => Float32x4, 17 => Float32x4];
/// Ground-marker per-instance attributes (`GroundMarkerInstanceRaw`): model columns 0-3, color 4,
/// the rounded-box SDF's `(half_extent, radius, pad)` lane 5.
const GROUND_MARKER_INSTANCE_ATTRS: [wgpu::VertexAttribute; 6] = wgpu::vertex_attr_array![0 => Float32x4, 1 => Float32x4, 2 => Float32x4, 3 => Float32x4, 4 => Float32x4, 5 => Float32x4];
/// Sprite per-instance attributes (`SpriteInstanceRaw`: center/right/up/color, then the UV rect, the
/// flags lane, the hit-flash lane, and the tiling/scroll lane), locations 0-7.
const SPRITE_INSTANCE_ATTRS: [wgpu::VertexAttribute; 8] = wgpu::vertex_attr_array![0 => Float32x3, 1 => Float32x3, 2 => Float32x3, 3 => Float32x4, 4 => Float32x4, 5 => Uint32, 6 => Float32x4, 7 => Float32x4];
/// Particle per-instance attributes (`ParticleInstanceRaw`: center/right/up/color, then the
/// `(size, softness, additive, pad)` lane), locations 0-4.
const PARTICLE_INSTANCE_ATTRS: [wgpu::VertexAttribute; 5] = wgpu::vertex_attr_array![0 => Float32x3, 1 => Float32x3, 2 => Float32x3, 3 => Float32x4, 4 => Float32x4];
/// Text per-vertex attributes (`TextVertexRaw`: position/uv/color/sdf), locations 0-3.
const TEXT_VERTEX_ATTRS: [wgpu::VertexAttribute; 4] =
    wgpu::vertex_attr_array![0 => Float32x3, 1 => Float32x2, 2 => Float32x4, 3 => Float32];
/// UI-rect per-instance attributes (`UiRectInstanceRaw`: rect/color/uv-sub-rect), locations 0-2.
const UI_RECT_INSTANCE_ATTRS: [wgpu::VertexAttribute; 3] =
    wgpu::vertex_attr_array![0 => Float32x4, 1 => Float32x4, 2 => Float32x4];
/// UI-text per-vertex attributes (`UiTextVertexRaw`: position/uv/color/sdf), locations 0-3.
const UI_TEXT_VERTEX_ATTRS: [wgpu::VertexAttribute; 4] =
    wgpu::vertex_attr_array![0 => Float32x2, 1 => Float32x2, 2 => Float32x4, 3 => Float32];
/// Debug-line per-vertex attributes (`DebugLineVertexRaw`: position/color), locations 0-1.
const DEBUG_LINE_VERTEX_ATTRS: [wgpu::VertexAttribute; 2] =
    wgpu::vertex_attr_array![0 => Float32x3, 1 => Float32x4];
/// The shadow pass's slope-scaled depth bias: it follows the map's texel size and the surface's
/// grazing angle, so the authored constant bias can stay small. The constant term is left at zero —
/// a `Depth32Float` constant unit is exponent-relative, so it cannot be authored in world units.
const SHADOW_SLOPE_BIAS: f32 = 1.5;
/// Shadow-caster per-vertex attributes: the position (`MeshVertex`'s first field, location 0) plus
/// the skin weights/bones (locations 18-19, hand-built since the macro's sequential offsets assume
/// every field between the declared locations is also declared — `weights`/`bones` are the last two
/// fields but position is the first, so this array cannot be one contiguous macro run). The shadow
/// pipeline reuses the mesh `MeshVertex` buffer; the other per-vertex attributes are simply not
/// declared.
const SHADOW_VERTEX_ATTRS: [wgpu::VertexAttribute; 3] = [
    wgpu::VertexAttribute {
        format: wgpu::VertexFormat::Float32x3,
        offset: 0,
        shader_location: 0,
    },
    wgpu::VertexAttribute {
        format: wgpu::VertexFormat::Float32x4,
        offset: std::mem::offset_of!(MeshVertex, weights) as u64,
        shader_location: 18,
    },
    wgpu::VertexAttribute {
        format: wgpu::VertexFormat::Uint32x4,
        offset: std::mem::offset_of!(MeshVertex, bones) as u64,
        shader_location: 19,
    },
];
/// Shadow-caster per-instance attributes: the model-matrix rows (`MeshInstanceRaw`'s first field,
/// locations 6-9 at offsets 0/16/32/48) plus the bone-palette offset lane (`fade`, location 16,
/// hand-built for the same reason the vertex array is — color/material/normal sit between the model
/// rows and `fade` in `MeshInstanceRaw` but are not declared here). Reuses the mesh instance buffer;
/// `flash` is not declared (the depth-only shadow shader never reads it).
const SHADOW_INSTANCE_ATTRS: [wgpu::VertexAttribute; 5] = [
    wgpu::VertexAttribute {
        format: wgpu::VertexFormat::Float32x4,
        offset: 0,
        shader_location: 6,
    },
    wgpu::VertexAttribute {
        format: wgpu::VertexFormat::Float32x4,
        offset: 16,
        shader_location: 7,
    },
    wgpu::VertexAttribute {
        format: wgpu::VertexFormat::Float32x4,
        offset: 32,
        shader_location: 8,
    },
    wgpu::VertexAttribute {
        format: wgpu::VertexFormat::Float32x4,
        offset: 48,
        shader_location: 9,
    },
    wgpu::VertexAttribute {
        format: wgpu::VertexFormat::Float32x4,
        offset: std::mem::offset_of!(MeshInstanceRaw, fade) as u64,
        shader_location: 16,
    },
];

/// `front_face` is `Cw` for the mirrored twin: a model matrix with a negative determinant reverses
/// triangle winding, so its outside faces would otherwise be the culled ones.
fn build_mesh_pipeline(
    device: &wgpu::Device,
    label: &str,
    src: &str,
    layout: &wgpu::PipelineLayout,
    front_face: wgpu::FrontFace,
) -> wgpu::RenderPipeline {
    // `src` is the already-composed source (camera + lights snippets + the mesh body); the caller
    // (`Renderer::compose` / `builtin_composed`) did the composition, so this just builds the module.
    let shader = module(device, label, src);
    device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
        label: Some(label),
        layout: Some(layout),
        vertex: wgpu::VertexState {
            module: &shader,
            entry_point: Some("vs_main"),
            buffers: &[
                Some(wgpu::VertexBufferLayout {
                    array_stride: std::mem::size_of::<MeshVertex>() as u64,
                    step_mode: wgpu::VertexStepMode::Vertex,
                    attributes: &MESH_VERTEX_ATTRS,
                }),
                Some(wgpu::VertexBufferLayout {
                    array_stride: std::mem::size_of::<MeshInstanceRaw>() as u64,
                    step_mode: wgpu::VertexStepMode::Instance,
                    attributes: &MESH_INSTANCE_ATTRS,
                }),
            ],
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        },
        fragment: Some(wgpu::FragmentState {
            module: &shader,
            entry_point: Some("fs_main"),
            targets: &[Some(wgpu::ColorTargetState {
                format: HDR_FORMAT,
                blend: None,
                write_mask: wgpu::ColorWrites::ALL,
            })],
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        }),
        primitive: wgpu::PrimitiveState {
            cull_mode: Some(wgpu::Face::Back),
            front_face,
            ..Default::default()
        },
        depth_stencil: Some(depth_state(true, wgpu::CompareFunction::Less)),
        multisample: wgpu::MultisampleState::default(),
        multiview_mask: None,
        cache: None,
    })
}

/// The depth-only sun shadow pipeline: no color target, no fragment stage. Reuses the mesh vertex +
/// instance buffers (reading only position + the model rows), writes depth `Less`, back-face culled
/// like the main mesh pass — the conventional baseline; a small constant shader bias
/// (`Sun.direction.w`) handles acne, with peter-panning kept minimal at the pinned default.
///
/// `front_face` is `Cw` for the mirrored twin: a model matrix with a negative determinant reverses
/// triangle winding, so its outside faces would otherwise be the culled ones.
fn build_shadow_pipeline(
    device: &wgpu::Device,
    label: &str,
    src: &str,
    layout: &wgpu::PipelineLayout,
    front_face: wgpu::FrontFace,
) -> wgpu::RenderPipeline {
    let shader = module(device, label, src);
    device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
        label: Some(label),
        layout: Some(layout),
        vertex: wgpu::VertexState {
            module: &shader,
            entry_point: Some("vs_main"),
            buffers: &[
                Some(wgpu::VertexBufferLayout {
                    array_stride: std::mem::size_of::<MeshVertex>() as u64,
                    step_mode: wgpu::VertexStepMode::Vertex,
                    attributes: &SHADOW_VERTEX_ATTRS,
                }),
                Some(wgpu::VertexBufferLayout {
                    array_stride: std::mem::size_of::<MeshInstanceRaw>() as u64,
                    step_mode: wgpu::VertexStepMode::Instance,
                    attributes: &SHADOW_INSTANCE_ATTRS,
                }),
            ],
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        },
        // Depth-only: no fragment stage, no color targets.
        fragment: None,
        primitive: wgpu::PrimitiveState {
            cull_mode: Some(wgpu::Face::Back),
            front_face,
            ..Default::default()
        },
        depth_stencil: Some(wgpu::DepthStencilState {
            bias: wgpu::DepthBiasState {
                constant: 0,
                slope_scale: SHADOW_SLOPE_BIAS,
                clamp: 0.0,
            },
            ..depth_state(true, wgpu::CompareFunction::Less)
        }),
        multisample: wgpu::MultisampleState::default(),
        multiview_mask: None,
        cache: None,
    })
}

/// The depth+normal prepass pipeline: the mesh pass's geometry drawn into an HDR normal target plus
/// its own depth attachment, with the same `Less` depth write and back-face culling. It reuses the
/// mesh vertex *and* instance attribute arrays verbatim — `prepass.wgsl` declares all twenty
/// locations even though it reads six — because the alternative is a third attribute array with
/// hand-computed byte offsets into the middle of [`MeshInstanceRaw`], which the `vertex_attr_array!`
/// macro cannot express and which nothing would catch if it drifted.
///
/// `front_face` is `Cw` for the mirrored twin: a model matrix with a negative determinant reverses
/// triangle winding, so its outside faces would otherwise be the culled ones.
fn build_prepass_pipeline(
    device: &wgpu::Device,
    label: &str,
    src: &str,
    layout: &wgpu::PipelineLayout,
    front_face: wgpu::FrontFace,
) -> wgpu::RenderPipeline {
    let shader = module(device, label, src);
    device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
        label: Some(label),
        layout: Some(layout),
        vertex: wgpu::VertexState {
            module: &shader,
            entry_point: Some("vs_main"),
            buffers: &[
                Some(wgpu::VertexBufferLayout {
                    array_stride: std::mem::size_of::<MeshVertex>() as u64,
                    step_mode: wgpu::VertexStepMode::Vertex,
                    attributes: &MESH_VERTEX_ATTRS,
                }),
                Some(wgpu::VertexBufferLayout {
                    array_stride: std::mem::size_of::<MeshInstanceRaw>() as u64,
                    step_mode: wgpu::VertexStepMode::Instance,
                    attributes: &MESH_INSTANCE_ATTRS,
                }),
            ],
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        },
        fragment: Some(wgpu::FragmentState {
            module: &shader,
            entry_point: Some("fs_main"),
            targets: &[Some(wgpu::ColorTargetState {
                format: HDR_FORMAT,
                blend: None,
                write_mask: wgpu::ColorWrites::ALL,
            })],
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        }),
        primitive: wgpu::PrimitiveState {
            cull_mode: Some(wgpu::Face::Back),
            front_face,
            ..Default::default()
        },
        depth_stencil: Some(depth_state(true, wgpu::CompareFunction::Less)),
        multisample: wgpu::MultisampleState::default(),
        multiview_mask: None,
        cache: None,
    })
}

/// The procedural sky pipeline: a fullscreen triangle (no vertex buffer — positions from
/// `vertex_index`) drawn inside the scene pass at far depth. Depth compare LessEqual with **no depth
/// write**, so it fills only the pixels no mesh wrote closer; back-face culling off (the covering
/// triangle's winding is irrelevant). Targets the HDR scene texture like the mesh pass.
fn build_sky_pipeline(
    device: &wgpu::Device,
    label: &str,
    src: &str,
    layout: &wgpu::PipelineLayout,
) -> wgpu::RenderPipeline {
    let shader = module(device, label, src);
    device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
        label: Some(label),
        layout: Some(layout),
        vertex: wgpu::VertexState {
            module: &shader,
            entry_point: Some("vs_main"),
            buffers: &[],
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        },
        fragment: Some(wgpu::FragmentState {
            module: &shader,
            entry_point: Some("fs_main"),
            targets: &[Some(wgpu::ColorTargetState {
                format: HDR_FORMAT,
                blend: None,
                write_mask: wgpu::ColorWrites::ALL,
            })],
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        }),
        primitive: wgpu::PrimitiveState::default(),
        // Far depth, LessEqual, no write: draw only where the cleared background depth (1.0) survives.
        depth_stencil: Some(depth_state(false, wgpu::CompareFunction::LessEqual)),
        multisample: wgpu::MultisampleState::default(),
        multiview_mask: None,
        cache: None,
    })
}

/// The ground-marker pipeline: instanced flat quads, alpha-blended into the HDR scene target, depth
/// **tested but not written**.
///
/// `Less` with no write is what makes a telegraph behave like paint on the floor: the geometry
/// standing on it occludes it, and it occludes nothing itself — including the sprites and text drawn
/// after it in the same pass. Two-sided (no culling), because a marker seen from below is still the
/// same flat shape.
fn build_ground_marker_pipeline(
    device: &wgpu::Device,
    label: &str,
    src: &str,
    layout: &wgpu::PipelineLayout,
) -> wgpu::RenderPipeline {
    let shader = module(device, label, src);
    device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
        label: Some(label),
        layout: Some(layout),
        vertex: wgpu::VertexState {
            module: &shader,
            entry_point: Some("vs_main"),
            buffers: &[Some(wgpu::VertexBufferLayout {
                array_stride: std::mem::size_of::<GroundMarkerInstanceRaw>() as u64,
                step_mode: wgpu::VertexStepMode::Instance,
                attributes: &GROUND_MARKER_INSTANCE_ATTRS,
            })],
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        },
        fragment: Some(wgpu::FragmentState {
            module: &shader,
            entry_point: Some("fs_main"),
            targets: &[Some(wgpu::ColorTargetState {
                format: HDR_FORMAT,
                blend: Some(alpha_blend()),
                write_mask: wgpu::ColorWrites::ALL,
            })],
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        }),
        primitive: wgpu::PrimitiveState::default(),
        depth_stencil: Some(depth_state(false, wgpu::CompareFunction::Less)),
        multisample: wgpu::MultisampleState::default(),
        multiview_mask: None,
        cache: None,
    })
}

